    21						onClick={() => openLink(match[3])}
    22					>
    23						{match[2]}
    24					</button>,
    25				);
    26			} else if (match[4]) {
    27				nodes.push(<strong key={index}>{match[4]}</strong>);
    28			} else if (match[5]) {
    29				nodes.push(<del key={index}>{match[5]}</del>);
