   206										checked={item.checked}
   207										readOnly
   208										disabled
   209										className="mt-0.5"
   210									/>
   211								) : null}
   212								<span>{inlineMarkdown(item.text, openLink)}</span>
   213							</li>
   214						))}
   215					</Tag>,
   216				);
   217				continue;
   218			}
   219	
   220			if (line.startsWith("> ")) {
   221				blocks.push(
   222					<blockquote
   223						key={`quote:${index}`}
   224						className="border-border border-l-2 pl-3 text-muted-foreground"
   225					>
   226						{inlineMarkdown(line.slice(2), openLink)}
   227					</blockquote>,
   228				);
   229				index++;
   230				continue;
   231			}
   232	
   233			const paragraph = [line.trim()];
   234			index++;
   235			while (
   236				index < lines.length &&
   237				lines[index].trim() &&
   238				!/^(#{1,4})\s|^\s*([-*+] |\d+\. )|^> |^```/.test(lines[index])
