   240				if (
   241					lines[index].includes("|") &&
   242					/^\s*\|?\s*:?-{3,}/.test(lines[index + 1] ?? "")
   243				)
   244					break;
   245				paragraph.push(lines[index].trim());
   246				index++;
   247			}
   248			blocks.push(
   249				<p key={`paragraph:${index}`} className="whitespace-pre-wrap">
   250					{inlineMarkdown(paragraph.join(" "), openLink)}
   251				</p>,
   252			);
   253		}
   254	
   255		return <div className="space-y-2 text-sm">{blocks}</div>;
   256	};

