   827	function renderNode(
   828		node: McpJsonNode,
   829		context: RenderContext,
   830		key?: string | number,
   831	): ReactNode {
   832		if (!isRecord(node) || typeof node.type !== "string") return null;
   833		if (node.type === "text")
   834			return typeof node.content === "string" ? node.content : null;
   835		if (node.type === "data") {
   836			const value = getValueByPath(context.data, String(node.path ?? ""));
   837			const resolved = value === undefined ? node.fallback : value;
   838			return formatValue(resolved, node.format as ValueFormat | undefined);
   839		}
   840		if (node.type === "if") {
   841			const branch = getValueByPath(context.data, String(node.condition ?? ""))
   842				? node.then
   843				: node.else;
   844			return isRecord(branch)
   845				? renderNode(branch as McpJsonNode, context, key)
   846				: null;
   847		}
