   103	}
   104	
   105	/** Coerce a stored view template (JSON string or object) to a render node, or null. */
   106	function coerceTemplate(raw: unknown): TemplateNode | null {
   107	  if (raw == null) return null;
   108	  let tpl: unknown = raw;
   109	  if (typeof raw === 'string') {
   110	    try {
   111	      tpl = JSON.parse(raw);
   112	    } catch {
   113	      return null;
   114	    }
   115	  }
   116	  if (!tpl || typeof tpl !== 'object' || Array.isArray(tpl)) return null;
   117	  if (Object.keys(tpl as object).length === 0) return null;
   118	  return tpl as TemplateNode;
   119	}
   120	
   121	/**
   122	 * The ONE render-resolution primitive — a declared view template wins; otherwise
   123	 * auto-default from the metadata schema. Returns the renderer ROOT NODE, or null
   124	 * when neither a template nor usable schema properties exist (free-form type →
   125	 * dashboard).
   126	 *
   127	 * Every render surface reuses this so a type renders identically everywhere:
   128	 * entity detail (`resolve_path`) and event render (`get_content`). Surface-specific
   129	 * overrides (an entity instance's own template, an event kind's `jsonTemplate`) are
   130	 * applied by the caller as the first argument; the type's declared `viewTemplate`
   131	 * is the fallback that this helper consults before auto-defaulting.
   132	 */
   133	export function resolveEntityRender(
   134	  declaredTemplate: unknown,
   135	  metadataSchema: Record<string, unknown> | null | undefined
   136	): TemplateNode | null {
   137	  return coerceTemplate(declaredTemplate) ?? buildDefaultEntityTemplate(metadataSchema);
   138	}

