824	const INTERACTION_BUNDLE = "/mcp-apps/interaction/index.html";
825	
826	/** Adapt a react-query mutation into a `Promise<isError>` the iframe bridge can
827	 *  resolve its `tools/call` on. */
828	function runMutation(
829		run: (opts: { onSettled: (data: unknown, error: unknown) => void }) => void,
830	): Promise<boolean> {
831		return new Promise((resolve) => {
832			run({ onSettled: (_data, error) => resolve(Boolean(error)) });
833		});
834	}
835	
836	/**
837	 * Generic MCP App host: renders a `ui://` bundle in a sandboxed iframe
838	 * (`sandbox="allow-scripts"`, opaque origin, no cookies/DOM) and uses the stable
839	 * MCP Apps AppBridge lifecycle. The bundle receives tool input/result
840	 * notifications, reports size changes, and asks the host to broker tool calls
841	 * or external links. It never touches the API directly.
842	 */
843	const McpAppFrame: FC<{
844		src: string;
845		title: string;
846		renderPayload: InteractionView;
847		onToolCall: (name: string, args: Record<string, unknown>) => Promise<boolean>;
848		onOpenLink: (url: string) => Promise<boolean>;
849	}> = ({ src, title, renderPayload, onToolCall, onOpenLink }) => {
850		const iframeRef = useRef<HTMLIFrameElement>(null);
851		const [height, setHeight] = useState(48);
852	
853		// Hold the render payload + broker in a ref so the message bridge subscribes
854		// to `window` exactly once and never re-attaches on a parent re-render (which
855		// would race an already-initialized iframe).
856		const stateRef = useRef({ renderPayload, onToolCall, onOpenLink });
857		stateRef.current = { renderPayload, onToolCall, onOpenLink };
858	
859		useEffect(() => {
860			const iframe = iframeRef.current;
861			if (!iframe?.contentWindow) return;
862	
863			const bridge = new AppBridge(
864				null,
865				{ name: "Lobu", version: "1.0.0" },
866				{ openLinks: {}, serverTools: {} },
867				{
868					hostContext: {
869						theme: document.documentElement.classList.contains("dark")
870							? "dark"
871							: "light",
872						displayMode: "inline",
873						platform: "web",
874					},
875				},
876			);
877			bridge.addEventListener("sizechange", ({ height: nextHeight }) => {
878				if (typeof nextHeight === "number") {
879					setHeight(Math.max(32, Math.ceil(nextHeight)));
880				}
881			});
882			bridge.oncalltool = async ({ name, arguments: toolArgs }) => ({
883				content: [],
884				isError: await stateRef.current.onToolCall(name, toolArgs ?? {}),
885			});
886			bridge.onopenlink = async ({ url }) => ({
887				isError: await stateRef.current.onOpenLink(url),
888			});
889			bridge.addEventListener("initialized", () => {
890				void (async () => {
891					await bridge.sendToolInput({ arguments: {} });
892					await bridge.sendToolResult({
893						content: [],
894						structuredContent: {
895							...stateRef.current.renderPayload,
896							version: 1,
897							source: SPA_HOSTED_VIEW_SOURCE,
898						},
899					});
900				})();
901			});
902	
903			const transport = new PostMessageTransport(
904				iframe.contentWindow,
905				iframe.contentWindow,
906			);
907			void bridge.connect(transport).catch((error) => {
908				console.error("[mcp-app-host] failed to initialize", error);
909			});
910			const themeObserver = new MutationObserver(() => {
911				bridge.setHostContext({
912					theme: document.documentElement.classList.contains("dark")
913						? "dark"
914						: "light",
915					displayMode: "inline",
916					platform: "web",
917				});
918			});
919			themeObserver.observe(document.documentElement, {
920				attributes: true,
921				attributeFilter: ["class"],
922			});
923			return () => {
924				themeObserver.disconnect();
925				void transport.close();
926			};
927		}, []);
928	
929		return (
930			<iframe
931				ref={iframeRef}
932				title={title}
933				src={src}
934				sandbox="allow-scripts"
935				style={{ width: "100%", height, border: "none", display: "block" }}
936			/>
937		);
938	};
939	
940	/** The interaction card args the chat store folds from an SSE card payload. */
941	type InteractionArgs = {
942		runId?: unknown;
943		action?: string | null;
944		proposal?: Record<string, unknown> | null;
945		current?: Record<string, unknown> | null;
946		requestId?: string | null;
947		tool?: string;
948		args?: unknown;
949		durationOptions?: unknown;
950		approveUrl?: string;
450		}),
451	);
452	
453	// Add security headers for ChatGPT connector safety
454	app.use("/*", async (c, next) => {
455		await next();
456	
457		// Security headers required for safe API access
458		c.header("X-Content-Type-Options", "nosniff");
459		// Changed from DENY to SAMEORIGIN to allow ChatGPT connector validation
460		c.header("X-Frame-Options", "SAMEORIGIN");
461		c.header("X-XSS-Protection", "1; mode=block");
462		c.header("Strict-Transport-Security", "max-age=31536000; includeSubDomains");
463	
464		// For HTML responses (SPA entrypoints), add a CSP frame-ancestors directive
465		// that allows the lobu.ai landing page to embed the app. Modern browsers
466		// prefer frame-ancestors over X-Frame-Options when both are present, so this
467		// effectively loosens the SAMEORIGIN restriction for our own properties while
468		// still blocking third-party clickjacking. JSON/API responses keep the
469		// stricter header and no CSP, preserving ChatGPT connector validation.
470		const contentType = c.res.headers.get("content-type") ?? "";
471		if (contentType.startsWith("text/html")) {
472			const rawFrameAncestors = c.env.FRAME_ANCESTORS?.trim();
473			const frameAncestors = rawFrameAncestors
474				? rawFrameAncestors
475						.split(/[\s,]+/)
476						.map((entry) => entry.trim())
477						.filter((entry) => isValidFrameAncestor(entry))
478						.join(" ")
479				: "https://lobu.ai https://*.lobu.ai";
480			// Owletto for Chrome embeds the whole app in its sidepanel iframe —
481			// not just a stub route, the same UI users get in a regular tab. To
482			// allow that without opening clickjacking risk to every extension on
483			// the user's machine, we narrow the allow to OUR extension IDs (see
484			// getOwnedOwlettoExtensionIds — same list the CORS allowlist uses).
485			const extensionAllowed = getOwnedOwlettoExtensionIds(c.env)
486				.map((id) => ` chrome-extension://${id}`)
487				.join("");
488			c.header(
489				"Content-Security-Policy",
490				`frame-ancestors 'self' ${frameAncestors}${extensionAllowed}`,
491			);
492		}
493	
494		c.header("Referrer-Policy", "strict-origin-when-cross-origin");
495		// Minimal permissions policy to prevent FLoC without blocking ChatGPT validation
496		c.header("Permissions-Policy", "interest-cohort=()");
497	});
498	
499	/**
500	 * Subdomain org extraction middleware
501	 * Parses Host header for {org}.{zone} pattern and sets subdomainOrg.
502	 * The zone is AUTH_COOKIE_DOMAIN when set (so per-org hosts like `acme.lobu.ai`
503	 * resolve even though PUBLIC_GATEWAY_URL is `app.lobu.ai`), otherwise the
504	 * PUBLIC_GATEWAY_URL hostname. Reserved subdomains (www, api, app, admin, etc.)
505	 * are not treated as orgs.
506	 */
507	const RESERVED_SUBDOMAINS = new Set([
508		"www",
509		"api",
510		"app",
511		"admin",
512		"auth",
513		"mcp",
514		"static",
515		"assets",
516		"cdn",
517		"docs",
518		"mail",
519	]);
